CREATE POLICY alerts_update ON public.alerts FOR UPDATE TO authenticated USING (public.has_org_role(organization_id, ARRAY['SUPER_ADMIN','ORGANIZATION_ADMIN','BRANCH_MANAGER','FLEET_MANAGER','DISPATCHER'])) WITH CHECK (public.has_org_role(organization_id, ARRAY['SUPER_ADMIN','ORGANIZATION_ADMIN','BRANCH_MANAGER','FLEET_MANAGER','DISPATCHER']) AND ((status = 'OPEN' AND acknowledged_by IS NULL AND resolved_by IS NULL) OR (status = 'ACKNOWLEDGED' AND acknowledged_by = auth.uid() AND resolved_by IS NULL) OR (status = 'RESOLVED' AND resolved_by = auth.uid())));